import pulp

# ----------------------------------------------------------------------
# Data
# ----------------------------------------------------------------------
plants = ["Alpha", "Beta", "Gamma", "Delta", "Epsilon", "Zeta", "Eta"]
cities = ["Delta", "Epsilon", "Zeta", "Eta", "Theta", "Iota", "Kappa"]

plant_capacity = {
    "Alpha": 20,
    "Beta": 12,
    "Gamma": 40,
    "Delta": 88,
    "Epsilon": 13,
    "Zeta": 85,
    "Eta": 75,
}

city_demand = {
    "Delta": 16,
    "Epsilon": 29,
    "Zeta": 69,
    "Eta": 43,
    "Theta": 24,
    "Iota": 85,
    "Kappa": 67,
}

line_capacity = {
    "Alpha": {
        "Delta": 25, "Epsilon": 68, "Zeta": 7, "Eta": 86,
        "Theta": 38, "Iota": 47, "Kappa": 22,
    },
    "Beta": {
        "Delta": 49, "Epsilon": 17, "Zeta": 83, "Eta": 76,
        "Theta": 58, "Iota": 13, "Kappa": 37,
    },
    "Gamma": {
        "Delta": 78, "Epsilon": 18, "Zeta": 71, "Eta": 14,
        "Theta": 80, "Iota": 21, "Kappa": 67,
    },
    "Delta": {
        "Delta": 9, "Epsilon": 71, "Zeta": 33, "Eta": 49,
        "Theta": 17, "Iota": 76, "Kappa": 95,
    },
    "Epsilon": {
        "Delta": 32, "Epsilon": 27, "Zeta": 93, "Eta": 89,
        "Theta": 34, "Iota": 56, "Kappa": 30,
    },
    "Zeta": {
        "Delta": 82, "Epsilon": 94, "Zeta": 100, "Eta": 61,
        "Theta": 49, "Iota": 25, "Kappa": 39,
    },
    "Eta": {
        "Delta": 97, "Epsilon": 49, "Zeta": 75, "Eta": 30,
        "Theta": 32, "Iota": 64, "Kappa": 45,
    },
}

transmission_cost = {
    "Alpha": {
        "Delta": 5, "Epsilon": 4, "Zeta": 7, "Eta": 7,
        "Theta": 9, "Iota": 6, "Kappa": 4,
    },
    "Beta": {
        "Delta": 10, "Epsilon": 5, "Zeta": 2, "Eta": 1,
        "Theta": 3, "Iota": 6, "Kappa": 10,
    },
    "Gamma": {
        "Delta": 10, "Epsilon": 8, "Zeta": 2, "Eta": 9,
        "Theta": 8, "Iota": 7, "Kappa": 6,
    },
    "Delta": {
        "Delta": 7, "Epsilon": 1, "Zeta": 2, "Eta": 7,
        "Theta": 10, "Iota": 3, "Kappa": 3,
    },
    "Epsilon": {
        "Delta": 1, "Epsilon": 2, "Zeta": 7, "Eta": 4,
        "Theta": 1, "Iota": 5, "Kappa": 5,
    },
    "Zeta": {
        "Delta": 7, "Epsilon": 2, "Zeta": 6, "Eta": 5,
        "Theta": 6, "Iota": 10, "Kappa": 4,
    },
    "Eta": {
        "Delta": 9, "Epsilon": 9, "Zeta": 1, "Eta": 6,
        "Theta": 9, "Iota": 9, "Kappa": 1,
    },
}

# ----------------------------------------------------------------------
# Model
# ----------------------------------------------------------------------
model = pulp.LpProblem("PowerDistribution", pulp.LpMinimize)

# Decision variables: x[p][c] = MW shipped from plant p to city c
x = pulp.LpVariable.dicts("x", (plants, cities), lowBound=0, cat="Continuous")

# ----------------------------------------------------------------------
# Objective: minimize total transmission cost
# ----------------------------------------------------------------------
model += pulp.lpSum(
    x[p][c] * transmission_cost[p][c] for p in plants for c in cities
), "Total_Transmission_Cost"

# ----------------------------------------------------------------------
# Requirement R1: Supply from each plant cannot exceed its generation capacity.
# ----------------------------------------------------------------------
for p in plants:
    model += (
        pulp.lpSum(x[p][c] for c in cities) <= plant_capacity[p],
        f"R1_{p}",
    )

# ----------------------------------------------------------------------
# Requirement R2: Flow on each transmission line cannot exceed its line capacity.
# ----------------------------------------------------------------------
for p in plants:
    for c in cities:
        model += (
            x[p][c] <= line_capacity[p][c],
            f"R2_{p}_{c}",
        )

# ----------------------------------------------------------------------
# Requirement R3: Total flow into each city must equal that city's demand.
# ----------------------------------------------------------------------
for c in cities:
    model += (
        pulp.lpSum(x[p][c] for p in plants) == city_demand[c],
        f"R3_{c}",
    )

# ----------------------------------------------------------------------
# Requirement R4: All flows must be non‑negative (named constraints).
# ----------------------------------------------------------------------
for p in plants:
    for c in cities:
        model += (
            x[p][c] >= 0,
            f"R4_{p}_{c}",
        )

# ----------------------------------------------------------------------
# Solve with HiGHS
# ----------------------------------------------------------------------
model.solve(pulp.HiGHS(msg=False, timeLimit=120))

# ----------------------------------------------------------------------
# Output results
# ----------------------------------------------------------------------
print(f"Status: {pulp.LpStatus[model.status]}")
print(f"Total transmission cost: {pulp.value(model.objective):.2f}")

print("\nFlows (MW):")
for p in plants:
    for c in cities:
        flow = x[p][c].varValue
        if flow is not None and flow > 1e-6:
            print(f"  {p} -> {c}: {flow:.2f}")
